template <typename T>
[[nodiscard]] constexpr std::string_view spelled() {
  if constexpr (std::is_same_v<T, int>) return "int";
  else if constexpr (std::is_same_v<T, int&>) return "int&";
  else if constexpr (std::is_same_v<T, int&&>) return "int&&";
  else if constexpr (std::is_same_v<T, const int&>) return "const int&";
  else return "something else";
}

template <typename T>
void show(std::string_view call, T&& arg) {
  std::cout << std::format("{:<24}T = {:<12}arg is {}\n", call, spelled<T>(), spelled<decltype(arg)>());
}

int main() {
  int count = 3;
  const int limit = 10;
  show("show(count)", count);
  show("show(limit)", limit);
  show("show(std::move(count))", std::move(count));
  show("show(42)", 42);
}

