#include <iostream>
#include <utility>

struct Tracer {
  Tracer() = default;
  Tracer(const Tracer&) { std::cout << "copy\n"; }
  Tracer(Tracer&&) noexcept { std::cout << "move\n"; }
  Tracer& operator=(const Tracer&) = default;
  Tracer& operator=(Tracer&&) = default;
  ~Tracer() = default;
};

void store(Tracer /*kept*/) {}

template <typename T>
void pass_by_name(T&& arg) {
  store(arg);
}

template <typename T>
void pass_moved(T&& arg) {
  store(std::move(arg));
}

template <typename T>
void pass_forwarded(T&& arg) {
  store(std::forward<T>(arg));
}

int main() {
  Tracer kept;
  std::cout << "by name,   lvalue: ";
  pass_by_name(kept);
  std::cout << "by name,   rvalue: ";
  pass_by_name(Tracer{});
  std::cout << "std::move, lvalue: ";
  pass_moved(kept);
  std::cout << "std::move, rvalue: ";
  pass_moved(Tracer{});
  std::cout << "forward,   lvalue: ";
  pass_forwarded(kept);
  std::cout << "forward,   rvalue: ";
  pass_forwarded(Tracer{});
}

