// Calls f exactly as the caller would have: same arguments, same value categories, same result.
template <typename F, typename... Args>
  requires std::invocable<F, Args...>
decltype(auto) call_logged(std::string_view label, F&& f, Args&&... args) {
  std::cout << std::format("calling {}\n", label);
  return std::invoke(std::forward<F>(f), std::forward<Args>(args)...);
}

void append_suffix(std::string& text) { text += ".bag"; }
void keep(Tracer /*kept*/) {}
[[nodiscard]] int& front_of(std::vector<int>& values) { return values.front(); }

int main() {
  std::string name = "run_07";
  call_logged("append_suffix", append_suffix, name);
  std::cout << std::format("  name is now {}\n", name);

  Tracer tracer;
  call_logged("keep with an lvalue", keep, tracer);
  call_logged("keep with an rvalue", keep, std::move(tracer));

  std::vector<int> gains{1, 2, 3};
  call_logged("front_of", front_of, gains) = 10;
  std::cout << std::format("  gains[0] is now {}\n", gains[0]);

  auto counter = [calls = 0]() mutable { return ++calls; };
  const int first = call_logged("counter", counter);
  const int second = call_logged("counter", counter);
  std::cout << std::format("  counter returned {}, then {}\n", first, second);
}

#include <concepts>
