struct LidarConfig {
  std::string frame_id;
  int rate_hz = 10;
};

class Sensor {
 public:
  virtual ~Sensor() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
};

class Lidar final : public Sensor {
 public:
  explicit Lidar(const LidarConfig& config) : config_(config) {
    std::cout << "  Lidar(const LidarConfig&): copies the config\n";
  }
  explicit Lidar(LidarConfig&& config) : config_(std::move(config)) {
    std::cout << "  Lidar(LidarConfig&&): moves the config\n";
  }
  Lidar(std::string_view frame_id, int rate_hz) : config_{.frame_id = std::string(frame_id), .rate_hz = rate_hz} {
    std::cout << "  Lidar(std::string_view, int): builds the config in place\n";
  }
  [[nodiscard]] std::string_view name() const override { return config_.frame_id; }

 private:
  LidarConfig config_;
};

class Imu final : public Sensor {
 public:
  Imu() { std::cout << "  Imu()\n"; }
  [[nodiscard]] std::string_view name() const override { return "imu"; }
};

class SensorRegistry {
 public:
  // Constructs an S from the caller's arguments, keeps it, and returns it.
  template <std::derived_from<Sensor> S, typename... Args>
    requires std::constructible_from<S, Args...>
  S& emplace(Args&&... args) {
    auto sensor = std::make_unique<S>(std::forward<Args>(args)...);
    S& added = *sensor;
    sensors_.push_back(std::move(sensor));
    return added;
  }
  [[nodiscard]] std::ptrdiff_t size() const { return std::ssize(sensors_); }

 private:
  std::vector<std::unique_ptr<Sensor>> sensors_;
};

int main() {
  SensorRegistry registry;
  const LidarConfig front{.frame_id = "front_lidar", .rate_hz = 20};
  LidarConfig rear{.frame_id = "rear_lidar", .rate_hz = 10};

  std::cout << "emplace<Lidar>(front):\n";
  const Lidar& first = registry.emplace<Lidar>(front);
  std::cout << "emplace<Lidar>(std::move(rear)):\n";
  registry.emplace<Lidar>(std::move(rear));
  std::cout << "emplace<Lidar>(\"top_lidar\", 5):\n";
  registry.emplace<Lidar>("top_lidar", 5);
  std::cout << "emplace<Imu>():\n";
  registry.emplace<Imu>();
  std::cout << std::format("{} sensors; the first is still {}\n", registry.size(), first.name());
}

