class Recorder {
 public:
  void record(std::string line) { lines_.push_back(std::move(line)); }
  [[nodiscard]] const std::string& last() const { return lines_.back(); }

 private:
  std::vector<std::string> lines_;
};

class Link {
 public:
  void send(std::string message) { sent_ = std::move(message); }
  [[nodiscard]] const std::string& last_sent() const { return sent_; }

 private:
  std::string sent_;
};

template <typename S>
void publish(Recorder& recorder, Link& link, S&& message) {
  recorder.record(std::forward<S>(message));  // moves an rvalue into the recorder
  link.send(std::forward<S>(message));        // then sends what the move left behind
}

int main() {
  Recorder recorder;
  Link link;
  publish(recorder, link, std::string("pose 12.5 3.0 heading 1.57 from the localiser"));
  std::cout << std::format("recorded: '{}'\nsent:     '{}'\n", recorder.last(), link.last_sent());
}

