#include <concepts>
#include <format>
#include <iostream>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>

class Topic {
 public:
  template <typename S>
    requires std::constructible_from<std::string, S> && (!std::derived_from<std::remove_cvref_t<S>, Topic>)
  explicit Topic(S&& name) : name_(std::forward<S>(name)), origin_(Origin::converted) {}
  Topic(const Topic& other) : name_(other.name_), origin_(Origin::copied) {}
  Topic(Topic&&) noexcept = default;
  Topic& operator=(const Topic&) = default;
  Topic& operator=(Topic&&) noexcept = default;
  ~Topic() = default;

  operator std::string_view() const { return name_; }  // lets a Topic stand in for its name
  [[nodiscard]] std::string_view made_by() const { return origin_ == Origin::copied ? "copied" : "converted"; }

 private:
  enum class Origin { converted, copied };
  std::string name_;
  Origin origin_;
};

class LatchedTopic : public Topic {
 public:
  using Topic::Topic;
};

int main() {
  Topic scan("scan");
  const Topic copy(scan);
  LatchedTopic map_topic("map");
  const Topic sliced(map_topic);
  std::cout << std::format("copy: {}, from a derived object: {}\n", copy.made_by(), sliced.made_by());
}
